};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        $c.stf.doLogSave('ULDSTF15650.xml', SCREN_PROCS_TP_CD_07);
        $c.data.downloadGridViewExcel(grd_Grid, {fileName: "ESG공시 목록", type: "8"});
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF15650.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name dts_DsclList_OnLoadError
 * @description dts_DsclList 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_DsclList_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_DsclList);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF15650.dts_DsclList_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_DsclList_OnLoadCompleted
 * @description dts_DsclList 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_DsclList_OnLoadCompleted = async function(rowcount) {
    try {
        if (dts_DsclList.errorMsg) {
            await $c.win.alert("OnLoadCompleted => " + dts_DsclList.errorMsg);
        } else {
            scwin.filterCnt = rowcount;
            dts_DsclList.UseFilter = true;
            // dts_DsclList.Filter();
            scwin.doCntSet();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF15650.dts_DsclList_OnLoadCompleted" });
    }
};

/**
 * @method
