        $c.cm.IsurcdSearch(txb_IsurCd, txb_com_abbrv);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF15650.img_Isu_Srh_onclick" });
    }
};

/**
 * @method
 * @name txb_IsurCd_onblur
 * @description txb_IsurCd 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_IsurCd_onblur = function() {
    try {
        if (stFocusGrid === false) {
            Grd_com_isur.style.display = "none";
        }
        if (txb_IsurCd.getValue() === "") {
            txb_com_abbrv.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF15650.txb_IsurCd_onblur" });
    }
};

/**
 * @method
 * @name txb_IsurCd_onfocus
 * @description txb_IsurCd 포커스 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_IsurCd_onfocus = function() {
    try {
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF15650.txb_IsurCd_onfocus" });
    }
};

/**
 * @method
 * @name txb_IsurCd_onkeyup
 * @description txb_IsurCd 키 입력 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_IsurCd_onkeyup = function() {
    try {
        if (txb_IsurCd.getValue() === "") {
            Grd_com_isur.style.display = "none";
        } else {
            if (window.event.keyCode === 40) {
                // 아래화살표눌렀을때 그리드로 포커스
                Grd_com_isur.focus();
            } else {
                $c.cm.fn_com_isur_nm(window.event.keyCode);
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF15650.txb_IsurCd_onkeyup" });
    }
};

