/**
 * @method
 * @name grd_Grid_OnDblClick
 * @description grd_Grid 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    try {
        let gAcptNo = 0;
        let tmpYN = 'N';
        if (colid === "ACPT_NOW_92014_YN") {
            tmpYN = dts_DsclList.getCellData(row, "ACPT_NOW_92014_YN");
            if (tmpYN === 'Y') {
                gAcptNo = dts_DsclList.getCellData(row, "NOW_92014_ACPT_NO");
                await $c.stf.openDisclViewer(gAcptNo, "R");
            }
        } else if (colid === "ACPT_NOW_92011_YN") {
            tmpYN = dts_DsclList.getCellData(row, "ACPT_NOW_92011_YN");
            if (tmpYN === 'Y') {
                gAcptNo = dts_DsclList.getCellData(row, "NOW_92011_ACPT_NO");
                await $c.stf.openDisclViewer(gAcptNo, "R");
            }
        } else if (colid === "BEF_DISCLS_YN") {
            tmpYN = dts_DsclList.getCellData(row, "BEF_DISCLS_YN");
            if (tmpYN === 'Y') {
                gAcptNo = dts_DsclList.getCellData(row, "BEF_ACPT_NO");
                await $c.stf.openDisclViewer(gAcptNo, "R");
            }
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF15650.grd_Grid_OnDblClick" });
    }
};

/**
 * @method
 * @name dts_DsclList_OnFilter
 * @description Dscl List On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.dts_DsclList_OnFilter = function(row) {
    try {
        if (scwin.mm === "0") {
            // 전체일 경우 모두 보여준다.
            return true;
        } else {
            if (dts_DsclList.getCellData(row, "ACNTCLS_MM") === scwin.mm) {
                scwin.filterCnt++;
                return true;
            } else {
                return false;
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF15650.dts_DsclList_OnFilter" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    // alert(getObjectValue(cmb_YYYY) +":"+ getObjectValue(cmb_MM));
    scwin.mm = cmb_MM.getValue();
    scwin.filterCnt = 0;
    const sbmOptions = {
        id : "sbm_dts_DsclList",
        action : "/DisclosureSearch.do",
        ref : "",
        target : "dts_DsclList=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setYYYY
 * @description set YYYY 처리
 * @returns {void}
 * @hidden N
 */
scwin.setYYYY = function() {
    const ToDay = new Date();
    const yyyy = parseInt(ToDay.getYear(), 10);
    let str = "";
    for (let i = yyyy; i >= (yyyy - 5); i--) {
        str += i + "^" + i + ",";
    }
    str = str.substring(0, str.length - 1);
    cmb_YYYY.CBData = str;
    cmb_YYYY.setValue(ToDay.getYear());
};

/**
 * @method
 * @name setMM
 * @description set MM 처리
 * @returns {void}
 * @hidden N
 */
scwin.setMM = function() {
    const yy = 12;
    let str = "0^전체,";
    for (let i = yy; i >= 1; i--) {
        if ((i + '').length === 1) str += ('0' + i) + "^" + ('0' + i) + ",";

        else str += i + "^" + i + ",";
    }
    str = str.substring(0, str.length - 1);
    cmb_MM.CBData = str;
    cmb_MM.setValue('0');
};

/**
 * @method
 * @name checkCond
 * @description check Cond 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkCond = async function() {
    await scwin.search();
};

/**
 * @method
 * @name doCntSet
 * @description txt_gen_duty
 * @returns {void}
 * @hidden N
 */
scwin.doCntSet = function() {
    // txt_gen_duty
    let tmpBigYN = 'N'; // 자산총액 2조원 이상여부
    let tmpFinYN = 'N'; // 금융업종 여부
    let tmpGenDisclsYN = 'N'; // 일반 기업지배구조보고서 제출여부
    let tmpFreeDisclsYN = 'N'; // 자율 기업지배구조보고서 제출여부
    let cntGenBig = 0; // 일반법인 자산총액 2조원 이상 개수
    let cntFinBig = 0; // 금융업종 자산총액 2조원 이상 개수
    let cntGenDisclsSubmit = 0; // 일반법인 기업지배 보고서 제출 개수
    let cntFinDisclsSubmit = 0; // 금융업종 기업지배 보고서 제출 개수
    const cntGenDisclsNotSubmit = 0; // 일반법인 기업지배 보고서 미제출 개수
    let cntFinDisclsNotSubmit = 0; // 금융업종 기업지배 보고서 미제출 개수
    let cntGenFreeDisclsSubmit = 0; // 일반법인 자율공시 기업지배 보고서 제출 개수
    let cntFinFreeDisclsSubmit = 0; // 금융업종 자율공시 기업지배 보고서 제출 개수

    for (let i = 1; i <= scwin.filterCnt; i++) {
        tmpBigYN = dts_DsclList.getCellData(i, "BIG_YN");
        tmpFinYN = dts_DsclList.getCellData(i, "FIN_YN");
        tmpGenDisclsYN = dts_DsclList.getCellData(i, "ACPT_NOW_92014_YN");
        tmpFreeDisclsYN = dts_DsclList.getCellData(i, "ACPT_NOW_92011_YN");
        if (tmpFinYN === 'N') {
            if (tmpBigYN === 'Y') {
                cntGenBig++;
            }
            if (tmpGenDisclsYN === 'Y') {
                cntGenDisclsSubmit++;
            }
            if (tmpFreeDisclsYN === 'Y') {
                cntGenFreeDisclsSubmit++;
            }
        } else {
            if (tmpBigYN === 'Y') {
                cntFinBig++;
            }
            if (tmpGenDisclsYN === 'Y') {
                cntFinDisclsSubmit++;
            } else {
                cntFinDisclsNotSubmit++;
            }
            if (tmpFreeDisclsYN === 'Y') {
                cntFinFreeDisclsSubmit++;
            }
        }
    }

    // alert(under2cnt);
    txt_gen_duty.setValue(cntGenBig);
    txt_gen_submit.setValue(cntGenDisclsSubmit);
    txt_gen_notsubmit.setValue((cntGenBig - cntGenDisclsSubmit));
    txt_gen_submit_free.setValue(cntGenFreeDisclsSubmit);
    // 금융회사의 경우 자산총액 값이 제대로 안들어와서 2조원 여부를 알 수 없어. 그냥 제출기업은 의무제출기업이라고 판단하기로 함.
    txt_fin_duty.setValue(cntFinDisclsSubmit);
    txt_fin_submit.setValue(cntFinDisclsSubmit);
    txt_fin_notsubmit.setValue((cntFinDisclsSubmit - cntFinDisclsSubmit)); // 얜 뭐 항상 0이네..
    txt_fin_submit_free.setValue(cntFinFreeDisclsSubmit);
    txt_all.setValue(cntGenBig + cntFinDisclsSubmit);
    txt_all_submit.setValue(cntGenDisclsSubmit + cntFinDisclsSubmit);
    txt_all_not_submit.setValue((cntGenBig - cntGenDisclsSubmit) + (cntFinDisclsSubmit - cntFinDisclsSubmit));
    txt_all_free_submit.setValue((cntGenFreeDisclsSubmit + cntFinFreeDisclsSubmit));
    $c.stf.fillGridHeaderTotalCntEsg(scwin.filterCnt, panel_page); // 총 건수

};
